    auto entries=paletteEntries();check(std::any_of(entries.begin(),entries.end(),[](const auto& entry){return entry.action==audioCrossfadeOpen&&entry.enabled;})&&std::any_of(entries.begin(),entries.end(),[](const auto& entry){return entry.action==audioFadesClear&&entry.enabled;}),"command search enables fade tools for selected audio");setPlaylistSelection({0});entries=paletteEntries();check(std::any_of(entries.begin(),entries.end(),[](const auto& entry){return entry.action==audioCrossfadeOpen&&!entry.enabled;}),"command search disables crossfade with fewer than two audio clips");
